head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > tooltipHideInputType]<br/>tooltipDisplay=true 일때 툴팁을 표시하지 않을 Cell 의 inputType 속성값을 설정합니다.",
    "validation" : [
        "콤마(',')를 구분자로 툴팁을 표시하지 않을 Cell 의 inputType 속성값 종류를 한 개 이상 설정합니다.",
        "tooltipHideInputType 에 설정한 inputType 의 Cell 은 원래 툴팁이 표시되는 값(잘림)이어도 마우스 오버 시 툴팁이 표시되지 않습니다.",
        "tooltipHideInputType 에 설정하지 않은 inputType 의 Cell 은 마우스 오버 시 툴팁이 표시됩니다.",
        "미설정 시, 모든 inputType 의 Cell 에서 잘림 조건을 만족하면 마우스 오버 시 툴팁이 표시됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con_tooltipHideInputType 초기값 보관 ("link" 설정 케이스로 시작)
    scwin.gVar = { "cTooltipHideInputType": "link" };

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - tooltipHideInputType 검증용 커스텀 GridView 를 인라인 정의로 생성한다.
//  - 고정 전제 : tooltipDisplay="true" (이 속성은 tooltipDisplay 가 true 일때만 의미가 있다)
//  - 검증은 "원래 툴팁이 표시되는 inputType" 두 종류로 구성한다.
//      col_text : 긴 값(잘림) text   -> 원래 잘림 시 툴팁 표시되는 타입
//      col_link : 긴 값(잘림) link   -> 원래 잘림 시 툴팁 표시되는 타입
//    con 값(cTooltipHideInputType)에 따라 해당 inputType Cell 의 툴팁만 차단되는지,
//    미지정 타입 Cell 은 그대로 표시되는지 대비한다. (secret/custom/spinner 는 원래
//    미표시라 hideInputType 대상으로 의미가 없어 사용하지 않는다.)
scwin.comp_init = async function () {
    // con 현재값 반영 (Target 재생성 버튼이 comp_init 재호출)
    scwin.gVar.cTooltipHideInputType = con_tooltipHideInputType.getValue();   // "link" / "text" / "" (미설정)

    // 동적 생성용 네임스페이스 (페이지 scope 에서 공통 strNameSpace 가 비어있을 수 있어 로컬 정의)
    let ns = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    // 기존 target / dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    let hideMsg = (scwin.gVar.cTooltipHideInputType === "") ? "미설정" : scwin.gVar.cTooltipHideInputType;
    $c.gcm.createLabel('label="[전제] tooltipDisplay=true 고정. tooltipHideInputType=(' + hideMsg + ').\n[전제] 대상 컬럼은 둘 다 원래 잘림 시 툴팁이 표시되는 타입: 주소(text) / 홈페이지(link).\n[절차] Body Cell 에 마우스를 오버하여 툴팁 표시 여부를 확인하세요(표시 시 하단 반환값 영역에 출력).\n[확인] hideInputType=link: 홈페이지(link) Cell 은 툴팁 미표시, 주소(text) Cell 은 표시. hideInputType=text: 주소(text) Cell 미표시, 홈페이지(link) Cell 은 표시. 미설정: 두 Cell 모두 표시."', '', 'label1');

    // dataList 생성 ($p.data.create 로 생성)
    let dlt = '<w2:dataList ' + ns + ' baseNode="list" id="dlt_bind" repeatNode="map">';
    dlt += '<w2:columnInfo>';
    dlt += '<w2:column dataType="text" id="col_text" name="col_text"></w2:column>';
    dlt += '<w2:column dataType="text" id="col_link" name="col_link"></w2:column>';
    dlt += '</w2:columnInfo>';
    dlt += '<w2:data use="true"></w2:data>';
    dlt += '</w2:dataList>';
    $p.data.create(dlt);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDC[arrDC.length - 1];
    scwin.dlt_bind.setJSON([
        { "col_text": "서울특별시 강남구 테헤란로 152 강남파이낸스센터 23층", "col_link": "https://www.inswave.com/products/websquare/intro/main.do" },
        { "col_text": "부산광역시 해운대구 센텀중앙로 79 센텀사이언스파크 18층", "col_link": "https://www.inswave.com/support/center/notice/list.do" }
    ], false);

    // tooltipHideInputType : con 값에 따라 설정/미설정 (미설정 시 속성 자체를 제외하여 기본값 "" 동작 확인)
    let hideAttr = (scwin.gVar.cTooltipHideInputType === "") ? "" : 'tooltipHideInputType="' + scwin.gVar.cTooltipHideInputType + '" ';

    // 커스텀 GridView 인라인 정의 (tooltipDisplay=true 고정, 좁은 폭으로 긴 값 잘림 유도)
    let strTarget = '<w2:gridView ' + ns + ' tooltipDisplay="true" ' + hideAttr + 'dataList="data:dlt_bind" checkAllType="false" id="" style="width:420px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" inputType="text" id="col_text" value="주소"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col_link" value="홈페이지"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="120" inputType="text" id="col_text" dataList="col_text"></w2:column>';
    strTarget += '<w2:column width="120" inputType="link" id="col_link" dataList="col_link"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    let grp_comp = document.querySelector('.tc_group_basic');
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 마우스오버로 툴팁이 표시된 셀을 클릭하면 현재 표시된 툴팁 정보를 return 영역에 출력
    scwin.attachTooltipClick();
}



// 표시된 툴팁 정보를 return 영역에 출력 (마우스오버 후 그 셀 클릭 시)
//  - 엔진은 셀 클릭의 기본/버블 처리 단계에서 hover 툴팁을 닫는다(display:none).
//    따라서 클릭의 캡처(capture) 단계 리스너로 잡아야 툴팁이 아직 살아있어 정상 출력된다.
//  - 리스너를 그리드 DOM 엘리먼트에 걸어 Body Cell 클릭을 커버한다.
//  - 마우스오버만 해서는 출력되지 않으며, 클릭 시점에 현재 hover 로 표시된 툴팁 값이 캡처된다.
scwin.attachTooltipClick = function () {
    let gridEl = scwin.target1.getElement ? scwin.target1.getElement() : document.getElementById(scwin.target1.getID());
    if (!gridEl) { return; }
    if (scwin.tooltipClickFn && scwin.tooltipClickEl) {
        scwin.tooltipClickEl.removeEventListener("click", scwin.tooltipClickFn, true);
    }
    scwin.tooltipClickFn = function () { $c.gcm.getTooltipInfo(wf_body_bottom); };
    scwin.tooltipClickEl = gridEl;
    gridEl.addEventListener("click", scwin.tooltipClickFn, true);
};
